# ==================== pb_eval ====================
"""Pure-Python hand evaluator (replaces eval7, which the official engine does not have).

Cards are ints 0..51: rank * 4 + suit, rank 0..12 = '2'..'A', suit 0..3 = 'c','d','h','s'.
evaluate(cards) takes 5 to 7 ints and returns an int: higher wins, equal splits.
Category is score >> 20 (0 high card .. 8 straight flush).
"""
pb_eval__RANKS = '23456789TJQKA'
pb_eval__SUITS = 'cdhs'
pb_eval__DECK = [r + s for r in pb_eval__RANKS for s in pb_eval__SUITS]
pb_eval__CARD_INT = {c: i for i, c in enumerate(pb_eval__DECK)}
pb_eval__INT_CARD = list(pb_eval__DECK)
pb_eval__HAND_TYPES = ('High Card', 'Pair', 'Two Pair', 'Trips', 'Straight', 'Flush', 'Full House', 'Quads', 'Straight Flush')
pb_eval___BIT = [1 << (c >> 2) for c in range(52)]
pb_eval___SUIT = [c & 3 for c in range(52)]
pb_eval___RANK = [c >> 2 for c in range(52)]

def pb_eval___build_tables():
    straight = [-1] * 8192
    top5 = [0] * 8192
    for m in range(8192):
        hi = -1
        for top in range(12, 3, -1):
            w = 31 << top - 4
            if m & w == w:
                hi = top
                break
        if hi < 0 and m & 4111 == 4111:
            hi = 3
        straight[m] = hi
        packed, n = (0, 0)
        for r in range(12, -1, -1):
            if m >> r & 1:
                packed = packed << 4 | r
                n += 1
                if n == 5:
                    break
        packed <<= 4 * (5 - n)
        top5[m] = packed
    return (straight, top5)
pb_eval___STRAIGHT, pb_eval___TOP5 = pb_eval___build_tables()

def pb_eval__evaluate(cards):
    """Score of the best five-card hand among 5..7 card ints. Higher is better."""
    sm = [0, 0, 0, 0]
    cnt = [0] * 13
    for c in cards:
        sm[c & 3] |= 1 << (c >> 2)
        cnt[c >> 2] += 1
    for m in sm:
        if m and bin(m).count('1') >= 5:
            sf = pb_eval___STRAIGHT[m]
            if sf >= 0:
                return 8 << 20 | sf
            flush = 5 << 20 | pb_eval___TOP5[m]
            break
    else:
        flush = 0
    quad = trip = trip2 = p1 = p2 = -1
    single = 0
    for r in range(12, -1, -1):
        n = cnt[r]
        if n == 0:
            continue
        if n == 1:
            single |= 1 << r
        elif n == 2:
            if p1 < 0:
                p1 = r
            elif p2 < 0:
                p2 = r
            else:
                single |= 1 << r
        elif n == 3:
            if trip < 0:
                trip = r
            elif trip2 < 0:
                trip2 = r
        else:
            quad = r
    if quad >= 0:
        rest = single
        for x in (trip, trip2, p1, p2):
            if x >= 0:
                rest |= 1 << x
        k = pb_eval___TOP5[rest] >> 16
        return 7 << 20 | quad << 16 | k << 12
    if trip >= 0 and (trip2 >= 0 or p1 >= 0):
        pair = max(trip2, p1)
        return 6 << 20 | trip << 16 | pair << 12
    if flush:
        return flush
    rmask = sm[0] | sm[1] | sm[2] | sm[3]
    st = pb_eval___STRAIGHT[rmask]
    if st >= 0:
        return 4 << 20 | st << 16
    if trip >= 0:
        k = pb_eval___TOP5[single]
        return 3 << 20 | trip << 16 | k >> 4 & 65280
    if p2 >= 0:
        rest = single
        k = pb_eval___TOP5[rest] >> 16
        return 2 << 20 | p1 << 16 | p2 << 12 | k << 8
    if p1 >= 0:
        k = pb_eval___TOP5[single]
        return 1 << 20 | p1 << 16 | k >> 4 & 65520
    return pb_eval___TOP5[single]

def pb_eval__category(score):
    return score >> 20

def pb_eval__handtype(score):
    return pb_eval__HAND_TYPES[score >> 20]


# ==================== pb_eval7 ====================
"""A pure-Python stand-in for the parts of eval7 that Apex, Oracle and cards.py call.

eval7 is a C extension and is not installed in the official engine, so the ported bots import
this module as `eval7`. Implemented: Card, HandRange (with .hands), evaluate, handtype,
py_hand_vs_range_monte_carlo, py_all_hands_vs_range.

Differences from eval7 (all deliberate):
* Villain hands are sampled at random from HandRange.hands. eval7 walks the list in order, which
  is the bug cards.py works around by shuffling, so the intended behaviour is kept.
* On the river, py_hand_vs_range_monte_carlo is exact (every hand in the range) instead of sampled.
* py_all_hands_vs_range shares one set of random samples per board and caches results per board,
  so repeated calls in a hand cost nothing.
* Every Monte Carlo loop respects BUDGET: iterations are scaled by BUDGET["scale"], and once
  time.perf_counter() passes BUDGET["deadline"] each loop stops early (after a small minimum).
"""
pb_eval7__BUDGET = {'scale': 1.0, 'deadline': None, 'min_iters': 48, 'early_stops': 0}
pb_eval7___rng = random.Random(20261107)
pb_eval7___evaluate = pb_eval__evaluate

class pb_eval7___Card(int):
    """A card as an int 0..51 (rank * 4 + suit) that prints like eval7's Card: 'As'."""

    def __str__(self):
        return pb_eval__INT_CARD[self]

    def __repr__(self):
        return 'Card(%r)' % pb_eval__INT_CARD[self]
pb_eval7___CARDS = [int.__new__(pb_eval7___Card, i) for i in range(52)]
pb_eval7___BY_NAME = {name: pb_eval7___CARDS[i] for i, name in enumerate(pb_eval__INT_CARD)}

def pb_eval7___card(text):
    return pb_eval7___BY_NAME[text[0].upper() + text[1].lower()]

def pb_eval7__Card(text):
    """eval7.Card('As'): the shared card object for that name."""
    return pb_eval7___card(text)

def pb_eval7__evaluate(cards):
    return pb_eval7___evaluate(cards)

def pb_eval7__handtype(score):
    return pb_eval__handtype(score)

def pb_eval7___class_combos(token):
    token = token.strip()
    r1, r2 = (token[0], token[1])
    suits = 'cdhs'
    out = []
    if r1 == r2:
        for i in range(4):
            for j in range(i + 1, 4):
                out.append((pb_eval7___card(r1 + suits[i]), pb_eval7___card(r2 + suits[j])))
    elif len(token) > 2 and token[2] == 's':
        for s in suits:
            out.append((pb_eval7___card(r1 + s), pb_eval7___card(r2 + s)))
    else:
        for s in suits:
            for t in suits:
                if s != t:
                    out.append((pb_eval7___card(r1 + s), pb_eval7___card(r2 + t)))
    return out

class pb_eval7__HandRange:
    """Only what the bots use: HandRange("AA,AKs,72o").hands = [((c1, c2), weight), ...]."""

    def __init__(self, text=''):
        hands = []
        for token in text.split(','):
            if token.strip():
                hands.extend(((h, 1.0) for h in pb_eval7___class_combos(token)))
        self.hands = hands

def pb_eval7___iters(n):
    return max(pb_eval7__BUDGET['min_iters'], int(n * pb_eval7__BUDGET['scale']))

def pb_eval7___late():
    d = pb_eval7__BUDGET['deadline']
    return d is not None and time.perf_counter() > d

def pb_eval7__py_hand_vs_range_monte_carlo(hero, hand_range, board, iters):
    """Heads-up equity of hero vs a villain drawn from hand_range.hands (uniform over the list)."""
    hero = list(hero)
    board = list(board)
    dead = set(hero) | set(board)
    villains = [h for h, _ in hand_range.hands if h[0] not in dead and h[1] not in dead]
    if not villains:
        return 0.5
    need = 5 - len(board)
    if need == 0:
        mine = pb_eval7___evaluate(hero + board)
        tally = {}
        for v in villains:
            tally[v] = tally.get(v, 0) + 1
        win = 0.0
        tot = 0
        for v, k in tally.items():
            s = pb_eval7___evaluate([v[0], v[1]] + board)
            if mine > s:
                win += k
            elif mine == s:
                win += 0.5 * k
            tot += k
        return win / tot
    rest = [c for c in pb_eval7___CARDS if c not in dead]
    n = pb_eval7___iters(iters)
    choice = pb_eval7___rng.choice
    sample = pb_eval7___rng.sample
    hb = hero + board
    win = 0.0
    done = 0
    for i in range(n):
        if i & 31 == 31 and done >= pb_eval7__BUDGET['min_iters'] and pb_eval7___late():
            pb_eval7__BUDGET['early_stops'] += 1
            break
        v0, v1 = choice(villains)
        drawn = sample(rest, need + 2)
        run = [c for c in drawn if c != v0 and c != v1][:need]
        a = pb_eval7___evaluate(hb + run)
        b = pb_eval7___evaluate([v0, v1] + board + run)
        if a > b:
            win += 1.0
        elif a == b:
            win += 0.5
        done += 1
    return win / max(done, 1)
pb_eval7___ALL_CACHE = {}

def pb_eval7__py_all_hands_vs_range(hand_range, villain_range, board, iters):
    """{(c1, c2): equity vs villain_range} for every hand in hand_range, on this board.

    Shared samples and per-board caching: cost is one evaluation per hand per sample, once."""
    board = list(board)
    need = 5 - len(board)
    key = (tuple(board), len(villain_range.hands), iters)
    entry = pb_eval7___ALL_CACHE.get(key)
    if entry is None:
        if len(pb_eval7___ALL_CACHE) > 64:
            pb_eval7___ALL_CACHE.clear()
        dead = set(board)
        villains = [h for h, _ in villain_range.hands if h[0] not in dead and h[1] not in dead]
        rest = [c for c in pb_eval7___CARDS if c not in dead]
        samples = []
        n = max(8, iters)
        for _ in range(n):
            v0, v1 = pb_eval7___rng.choice(villains)
            drawn = pb_eval7___rng.sample(rest, need + 6)
            run = [c for c in drawn if c != v0 and c != v1][:need]
            full = board + run
            samples.append((v0, v1, full, set(full) | {v0, v1}, pb_eval7___evaluate([v0, v1] + full)))
        entry = pb_eval7___ALL_CACHE[key] = (samples, {})
    samples, done = entry
    out = {}
    for h, _ in hand_range.hands:
        k = (h[0], h[1]) if h[0] > h[1] else (h[1], h[0])
        eq = done.get(k)
        if eq is None:
            a, b = h
            win = 0.0
            cnt = 0
            for v0, v1, full, used, vs in samples:
                if a in used or b in used:
                    continue
                s = pb_eval7___evaluate([a, b] + full)
                if s > vs:
                    win += 1.0
                elif s == vs:
                    win += 0.5
                cnt += 1
            eq = win / cnt if cnt else 0.5
            done[k] = eq
        out[h] = eq
    return out


# ==================== pb_types ====================
"""
No-Limit Texas Hold'em engine for bot-vs-bot testing.

- 2 to 6 players, stacks reset every hand by default (ACPC "Doyle's game" style)
- "raise to" semantics: a raise amount is the player's TOTAL bet on this street
- side pots, split pots, per-decision timeout (fold/check on timeout)
- illegal actions are coerced to the nearest legal action and counted
- duplicate dealing: the same deck can be replayed with seats rotated

Card format: 'As', 'Td', '9c', ... (rank + suit)
"""
pb_types__RANKS = '23456789TJQKA'
pb_types__SUITS = 'cdhs'
pb_types__DECK = [r + s for r in pb_types__RANKS for s in pb_types__SUITS]
pb_types__CARD = {c: pb_eval7__Card(c) for c in pb_types__DECK}
pb_types__STREETS = ['preflop', 'flop', 'turn', 'river']

@dataclass
class pb_types__Obs:
    """Everything a bot sees when it must act."""
    hand_id: int
    seat: int
    n_players: int
    button: int
    street: int
    hole: list
    board: list
    pot: int
    to_call: int
    my_bet: int
    current_bet: int
    min_raise_to: int
    max_raise_to: int
    stacks: list
    bets: list
    folded: list
    history: list
    bb: int
    sb: int
    start_stack: int
    time_limit: float
    seat_names: list = field(default_factory=list)

    @property
    def can_check(self):
        return self.to_call == 0

    @property
    def can_raise(self):
        return self.min_raise_to > 0

    @property
    def active_opponents(self):
        return [i for i in range(self.n_players) if i != self.seat and (not self.folded[i])]

    def position_from_button(self, seat=None):
        s = self.seat if seat is None else seat
        return (s - self.button) % self.n_players

class pb_types__Bot:
    """Base class. Override act(); optionally new_match() and hand_over()."""
    name = 'Bot'

    def new_match(self, seat, n_players, names):
        pass

    def act(self, obs: Obs):
        return ('check', 0) if obs.can_check else ('fold', 0)

    def hand_over(self, result: dict):
        """result keys: hand_id, button, history, board, shown {seat: [cards]},
        deltas [chips per seat], names, my_seat"""
        pass


